using System.Collections.Generic;using System.Linq;using UnityEngine;namespace GameLab.ColorMode{    public static class ColorSplash    {        public static List<IPaintable> paintables = new();        public static List<IPaintable> GetPaintablesInRadius(IPaintable currentPaintable, Vector3 origin, float radius)        {            paintables.RemoveAll(x => !(x as MonoBehaviour));            return paintables.Where(paintable => (                    Vector3.Distance(((MonoBehaviour)paintable).transform.position, origin) <= radius                    && paintable != currentPaintable                ))                .ToList();        }    }}